using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Identity;
namespace StockFlow.Models;
public class ApplicationUser : IdentityUser { [MaxLength(120)] public string FullName { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public bool IsActive { get; set; } = true; }
public class Product { public int Id { get; set; } [Required, MaxLength(40)] public string Sku { get; set; } = ""; [Required, MaxLength(160)] public string Name { get; set; } = ""; [MaxLength(80)] public string Category { get; set; } = "General"; [MaxLength(500)] public string? Description { get; set; } [Range(0, 999999999)] public decimal CostPrice { get; set; } [Range(0, 999999999)] public decimal SellingPrice { get; set; } [Range(0, 100000000)] public int QuantityOnHand { get; set; } [Range(0, 100000000)] public int ReorderLevel { get; set; } = 5; [MaxLength(80)] public string? Barcode { get; set; } public bool IsActive { get; set; } = true; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
public class Supplier { public int Id { get; set; } [Required, MaxLength(160)] public string Name { get; set; } = ""; [MaxLength(120)] public string? ContactName { get; set; } [EmailAddress, MaxLength(160)] public string? Email { get; set; } [MaxLength(40)] public string? Phone { get; set; } [MaxLength(250)] public string? Address { get; set; } [MaxLength(80)] public string? TaxNumber { get; set; } public bool IsActive { get; set; } = true; }
public enum PurchaseStatus { Draft, PendingApproval, Approved, Ordered, PartiallyReceived, Received, Rejected, Cancelled }
public class PurchaseOrder { public int Id { get; set; } [Required] public string OrderNumber { get; set; } = ""; public int SupplierId { get; set; } public Supplier? Supplier { get; set; } public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime? ExpectedAt { get; set; } public PurchaseStatus Status { get; set; } = PurchaseStatus.Draft; [MaxLength(1000)] public string? Notes { get; set; } public string CreatedBy { get; set; } = ""; public string? ApprovedBy { get; set; } public DateTime? ApprovedAt { get; set; } public List<PurchaseOrderLine> Lines { get; set; } = new(); }
public class PurchaseOrderLine { public int Id { get; set; } public int PurchaseOrderId { get; set; } public PurchaseOrder? PurchaseOrder { get; set; } public int ProductId { get; set; } public Product? Product { get; set; } [Range(1, 1000000)] public int QuantityOrdered { get; set; } public int QuantityReceived { get; set; } [Range(0, 999999999)] public decimal UnitCost { get; set; } }
public class Sale { public int Id { get; set; } [Required] public string SaleNumber { get; set; } = ""; public DateTime SoldAt { get; set; } = DateTime.UtcNow; [MaxLength(120)] public string? CustomerName { get; set; } public decimal Total { get; set; } public string RecordedBy { get; set; } = ""; public List<SaleLine> Lines { get; set; } = new(); }
public class SaleLine { public int Id { get; set; } public int SaleId { get; set; } public Sale? Sale { get; set; } public int ProductId { get; set; } public Product? Product { get; set; } public int Quantity { get; set; } public decimal UnitPrice { get; set; } }
public enum MovementType { Opening, PurchaseReceipt, Sale, AdjustmentIncrease, AdjustmentDecrease, Return, Reversal }
public class StockMovement { public long Id { get; set; } public int ProductId { get; set; } public Product? Product { get; set; } public MovementType Type { get; set; } public int QuantityChange { get; set; } public int BalanceAfter { get; set; } [MaxLength(500)] public string Reason { get; set; } = ""; [MaxLength(80)] public string Reference { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public string PerformedBy { get; set; } = ""; }
public class AuditLog { public long Id { get; set; } [MaxLength(120)] public string UserEmail { get; set; } = ""; [MaxLength(80)] public string Action { get; set; } = ""; [MaxLength(100)] public string EntityName { get; set; } = ""; [MaxLength(100)] public string EntityId { get; set; } = ""; [MaxLength(1000)] public string Details { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; }
